class TestCoreStringTransformations:

    def test_reverse_happy_path(self):
        """Test standard successful string reversal."""
        assert reverse_string("Python") == "nohtyP"

    def test_reverse_empty_edge_case(self):
        """Test reversal of an empty string."""
        assert reverse_string("") == ""

    @pytest.mark.parametrize("text, expected_count", [
        ("", 0),                     # Empty string
        ("   \t ", 0),              # Only whitespace
        ("one two three", 3),       # Standard case
        ("Multiple   spaces  here", 3) # Handling excessive internal whitespace
    ])
    def test_count_words_edge_cases(self, text: str, expected_count: int):
        """Test count_words with various spacing and empty input."""
        assert count_words(text) == expected_count

    @pytest.mark.parametrize("text, suffix, expected", [
        ("Hello world!", 3, "Hello-world"), # Should hit the default path (<= max_length if max_len is big enough)
        ("This text is very long and needs shortening", 5, "This..."), # Test standard truncation
        ("Short", 10, "Short")            # Not truncated
    ])
    def test_truncate_functionality(self, text: str, suffix: int, expected):
        """Test basic functionality of truncate."""
        if suffix == -1: # Used internal skip for bad parametrization setup
             return

        # Setting up a scenario where we force truncation at max length = len(suffix) + 5
        max_length = len("This text is very long and needs shortening") if "very long" in text else 20

        if "Short" == text: # Special case for non-truncating test
            result = truncate(text, max_length, suffix="...")
            assert result == expected.replace("-", "").strip("...") # Need to handle the fact that standard truncation uses '...'
            return


