class TestContentExtractionAndSlugify:

    def test_extract_emails_mixed_data(self):
        """Test extracting multiple, single, and invalid email formats."""
        text = "Contact me at user@domain.com or info-dept@corp.net. Invalid emails like a@b or @c.com are ignored."
        expected = ["user@domain.com", "info-dept@corp.net"]
        assert extract_emails(text) == expected

    def test_slug_conversion_mixed_data(self):
        """Test slug generation handling capitalization, special characters, and spaces."""
        tests = [
            ("The Amazing Article!", "the-amazing-article"), # Punctuation removal
            ("Python & Web Development", "python-web-development"), # Special chars (&)
            ("  leading and trailing space ", "leading-and-trailing-space"), # Trim spaces
            ("Multiple---Hyphens--Here", "multiple-hyphens-here") # Multiple separators collapse
        ]
        for text, expected in tests:
            assert slug(text) == expected

    def test_is_palindrome_mixed_data(self):
        """Test is_palindrome ignoring case and non-alphanumeric characters."""
        # Palindromes with spaces/punctuation
        assert is_palindrome("Race car") == True
        assert is_palindrome("A man, a plan, a canal: panama.") == True
        # Non-palindromes
        assert is_palindrome("Hello World!") == False
        # Edge cases
        assert is_palindrome("") == True
        assert is_palindrome("121") == True


