class TestAlgorithmicFormattingRules:

    def test_title_case_standard(self):
        """Test standard title casing."""
        assert title_case("hello world") == "Hello World"
        assert title_case("a quick brown fox") == "Quick Brown Fox"

    @pytest.mark.parametrize("input_text, expected_output", [
        # Core exceptions (prepositions/articles)
        ("the dog and the cat ran by the river", 
         "Dog And The Cat Ran By The River"),
        ("an apple to eat with a fork", 
         "Apple To Eat With A Fork"),
        # Mixed case handling
        ("a test for AND but or OR us",
         "Test For And But Or Us"),
        # Start of sentence override (first word always capitalized)
        ("the cat sat on an mat",
         "The Cat Sat On An Mat")
    ])
    def test_title_case_with_exceptions(self, input_text: str, expected_output: str):
        """Test the specific logic of title_case regarding known exceptions."""
        assert title_case(input_text) == expected_output

